bool ParseHex(const std::string&v,std::array<std::uint8_t,32>*o){if(v.size()!=64)return false;auto n=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};for(unsigned i=0;i<32;++i){int a=n(v[2*i]),b=n(v[2*i+1]);if(a<0||b<0)return false;(*o)[i]=static_cast<std::uint8_t>((a<<4)|b);}return true;}
mgt::P888A100ExecutionProfileV1 Profile(unsigned world){mgt::P888A100ExecutionProfileV1 p{};p.world=world;p.active_rows={12497,12498,12500};p.policy.batch_norm=mgt::A100BatchNormBackend::kRowTiledFp32StatsBf16Output;p.policy.xhat_storage=mgt::A100XhatStorage::kBf16;mgt::Bf16AlgorithmTable t;std::string h;if(mgt_cuda::BuildP888A100Sm80Cuda124Bf16AlgorithmTable(&t)!=mgt::Status::kOk||mgt::CanonicalBf16AlgorithmTableSha256(t,&h)!=mgt::Status::kOk||!ParseHex(h,&p.policy.algorithm_table_sha256))p.policy.algorithm_table_sha256.fill(0);p.ordinary_arena_bytes=256;p.pinned_host_bytes=64;p.source_sha256.fill(2);p.binary_sha256.fill(3);p.arena_layout_sha256.fill(4);return p;}
const mgt::A100ArenaSliceV1* Find(const mgt::A100StaticArenaPlanV1&p,mgt::A100ArenaSliceKind k){for(unsigned i=0;i<p.slice_count;++i)if(p.slices[i].kind==k)return&p.slices[i];return nullptr;}
template<class T>T* Ptr(const mgt_cuda::A100StaticArenaView&v,const mgt::A100ArenaSliceV1*s,std::uint64_t elements=0){return reinterpret_cast<T*>(static_cast<std::uint8_t*>(v.ordinary_base)+s->offset)+elements;}
__global__ void FillFloat(float*x,std::uint64_t n,float base,float step){std::uint64_t q=static_cast<std::uint64_t>(blockIdx.x)*blockDim.x+threadIdx.x;if(q<n)x[q]=base+step*static_cast<float>(q%97);}
__global__ void FillBf16(__nv_bfloat16*x,std::uint64_t n,float base,float step){std::uint64_t q=static_cast<std::uint64_t>(blockIdx.x)*blockDim.x+threadIdx.x;if(q<n)x[q]=__float2bfloat16_rn(base+step*static_cast<float>(q%31));}
bool LaunchFill(float*p,std::uint64_t n,float b,float s,cudaStream_t st){FillFloat<<<static_cast<unsigned>((n+255)/256),256,0,st>>>(p,n,b,s);return cudaPeekAtLastError()==cudaSuccess;}
bool LaunchFill(__nv_bfloat16*p,std::uint64_t n,float b,float s,cudaStream_t st){FillBf16<<<static_cast<unsigned>((n+255)/256),256,0,st>>>(p,n,b,s);return cudaPeekAtLastError()==cudaSuccess;}
}

int main(){const char*le=std::getenv("SLURM_LOCALID"),*we=std::getenv("SLURM_NTASKS"),*re=std::getenv("SLURM_PROCID");bool multi=le&&we&&re&&std::getenv("MGT_BN_ID")&&std::getenv("MGT_WEIGHT_ID")&&std::getenv("MGT_METRICS_ID");unsigned device=multi?std::strtoul(le,nullptr,10):0,world=multi?std::strtoul(we,nullptr,10):1,rank=multi?std::strtoul(re,nullptr,10):0;if(cudaSetDevice(device)!=cudaSuccess)return 1;auto profile=Profile(world);constexpr std::uint64_t input=72ULL*72*2560+2560,hidden=2560ULL*224+224,residual=16ULL*2*(224ULL*224+224),output=225,params=input+hidden+residual+output;constexpr unsigned rows=12497,capacity=12500;constexpr std::uint64_t affine_count=10000;mgt::A100StaticArenaBuildInfo ai{&profile,72,72,2560,224,16,1,capacity,params,affine_count,320};mgt::A100StaticArenaPlanV1 arena{};if(mgt::BuildA100StaticArenaPlan(ai,&arena)!=mgt::Status::kOk)return 2;profile.arena_layout_sha256=arena.layout_sha256;profile.ordinary_arena_bytes=arena.ordinary_bytes;profile.pinned_host_bytes=arena.pinned_host_bytes;ai.profile=&profile;mgt_cuda::A100Bf16RuntimeCreateInfo ci{};ci.arena_info=ai;ci.device_id=device;ci.rank=rank;ci.world=world;ci.bn_nccl_id_file=std::getenv("MGT_BN_ID");ci.weight_nccl_id_file=std::getenv("MGT_WEIGHT_ID");ci.metrics_nccl_id_file=std::getenv("MGT_METRICS_ID");ci.execution_profile=&profile;ci.profile_use=mgt::A100ExecutionProfileUse::kCandidateForTuner;mgt_cuda::A100Bf16Runtime*r=nullptr;if(mgt_cuda::CreateA100Bf16Runtime(ci,arena,&r)!=mgt::Status::kOk)return 3;mgt_cuda::A100StaticArenaView view{};if(mgt_cuda::QueryA100Bf16RuntimeView(r,&view)!=mgt::Status::kOk)return 4;auto stream=mgt_cuda::A100Bf16RuntimeComputeStream(r);auto*wb=Find(arena,mgt::A100ArenaSliceKind::kWeightsBf16);auto*wg=Find(arena,mgt::A100ArenaSliceKind::kWeightGradFp32);auto*wm=Find(arena,mgt::A100ArenaSliceKind::kWeightMFp32);auto*wv=Find(arena,mgt::A100ArenaSliceKind::kWeightVFp32);auto*af=Find(arena,mgt::A100ArenaSliceKind::kAffineStateFp32);if(!wb||!wg||!wm||!wv||!af)return 5;constexpr std::uint64_t layer_values=224ULL*224;if(!LaunchFill(Ptr<__nv_bfloat16>(view,wb),32*layer_values,-0.002f,0.00013f,stream)||!LaunchFill(Ptr<float>(view,af),5*affine_count,0.0f,0.0f,stream))return 6;auto*gamma=Ptr<float>(view,af),*beta=gamma+affine_count,*running_mean=beta+affine_count,*running_var=running_mean+affine_count;auto*saved_mean=Ptr<float>(view,wm),*dbeta=saved_mean+affine_count;auto*saved_inv=Ptr<float>(view,wv),*dgamma=saved_inv+affine_count;if(!LaunchFill(gamma,affine_count,1.0f,0.0f,stream)||!LaunchFill(beta,affine_count,0.02f,0.0f,stream)||!LaunchFill(running_var,affine_count,1.0f,0.0f,stream))return 7;mgt_cuda::Bf16BatchNormSiteView input_view{};if(mgt_cuda::QueryA100Bf16RuntimeBatchNormSite(r,1,0,&input_view)!=mgt::Status::kOk||!LaunchFill(input_view.activation,static_cast<std::uint64_t>(capacity)*224,-0.25f,0.017f,stream))return 8;mgt_cuda::Bf16ResidualStackBindings b{};b.input_activation=input_view.activation;std::uint64_t off=0;for(unsigned site=0;site<34;++site){auto*p=mgt_cuda::A100Bf16RuntimeBatchNormSitesPlan(r);unsigned f=p->sites[site].logical_features;b.gamma[site]=gamma+off;b.beta[site]=beta+off;b.running_mean[site]=running_mean+off;b.running_variance[site]=running_var+off;b.saved_mean[site]=saved_mean+off;b.saved_inv_std[site]=saved_inv+off;b.dgamma[site]=dgamma+off;b.dbeta[site]=dbeta+off;off+=f;}for(unsigned layer=0;layer<32;++layer){b.weights[layer]=Ptr<__nv_bfloat16>(view,wb,layer*layer_values);b.weight_grads[layer]=Ptr<float>(view,wg,layer*layer_values);}const __nv_bfloat16*out=nullptr;cudaEvent_t start=nullptr,stop=nullptr;cudaEventCreate(&start);cudaEventCreate(&stop);cudaEventRecord(start,stream);if(mgt_cuda::LaunchA100Bf16ResidualStackForward(r,b,rows,rows*world,&out)!=mgt::Status::kOk||!out)return 9;float*up=mgt_cuda::A100Bf16RuntimePreactivationScratch(r);if(!LaunchFill(up,static_cast<std::uint64_t>(capacity)*2560,0.1f,0.0001f,stream))return 10;float*input_grad=nullptr;if(mgt_cuda::LaunchA100Bf16ResidualStackBackward(r,b,up,rows,rows*world,&input_grad)!=mgt::Status::kOk||!input_grad)return 11;cudaEventRecord(stop,stream);if(cudaEventSynchronize(stop)!=cudaSuccess)return 12;float ms=0;cudaEventElapsedTime(&ms,start,stop);__nv_bfloat16 output_sample{};float samples[4]{};if(cudaMemcpy(&output_sample,out,sizeof(output_sample),cudaMemcpyDeviceToHost)!=cudaSuccess||cudaMemcpy(&samples[1],input_grad,sizeof(float),cudaMemcpyDeviceToHost)!=cudaSuccess||cudaMemcpy(&samples[2],b.weight_grads[0],sizeof(float),cudaMemcpyDeviceToHost)!=cudaSuccess||cudaMemcpy(&samples[3],b.weight_grads[31],sizeof(float),cudaMemcpyDeviceToHost)!=cudaSuccess)return 13;samples[0]=__bfloat162float(output_sample);for(float v:samples)if(!std::isfinite(v))return 14;if(rank==0)printf("bf16 residual stack rows=%u world=%u ms=%.3f output=%g dx=%g dw0=%g dw31=%g\n",rows,world,ms,samples[0],samples[1],samples[2],samples[3]);cudaEventDestroy(start);cudaEventDestroy(stop);return mgt_cuda::DestroyA100Bf16Runtime(r)==mgt::Status::kOk?0:15;}
